package com.fakelegacy.catalog;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import lombok.RequiredArgsConstructor;

@RestController
@RequiredArgsConstructor
public class StockController {

    private final ProductRepository productRepository;
    private final StockReservationRepository reservationRepository;

    @Value("${reservation.ttl-minutes:15}")
    private int defaultTtlMinutes;

    // C5: re-reserving an existing orderRef only extends the hold, it never adds quantities
    @PostMapping("/stock/reserve")
    @Transactional
    public ResponseEntity<Map<String, Object>> reserve(@RequestBody Map<String, Object> body) {
        String orderRef = text(body.get("orderRef"));
        if (orderRef == null) {
            return error(HttpStatus.BAD_REQUEST, "orderRef is required");
        }
        int ttl = defaultTtlMinutes;
        if (body.get("ttlMinutes") != null) {
            Integer parsed = integer(body.get("ttlMinutes"));
            if (parsed == null || parsed <= 0) {
                return error(HttpStatus.BAD_REQUEST, "ttlMinutes must be a positive integer");
            }
            ttl = parsed;
        }
        LocalDateTime now = LocalDateTime.now();
        LocalDateTime expiresAt = now.plusMinutes(ttl);

        List<StockReservation> existing = reservationRepository.findByOrderRef(orderRef);
        if (!existing.isEmpty()) {
            for (StockReservation r : existing) {
                if (!StockReservation.ACTIVE.equals(r.getStatus()) || !r.getExpiresAt().isAfter(now)) {
                    return error(HttpStatus.CONFLICT, "reservation is no longer active for " + orderRef);
                }
            }
            for (StockReservation r : existing) {
                r.setExpiresAt(expiresAt);
            }
            reservationRepository.saveAll(existing);
            return ResponseEntity.ok(summary(orderRef, "EXTENDED", expiresAt));
        }

        Map<String, Integer> wanted = parseItems(body.get("items"));
        if (wanted == null || wanted.isEmpty()) {
            return error(HttpStatus.BAD_REQUEST, "items must be a non-empty list of {sku, qty} with qty > 0");
        }
        List<Product> products = new ArrayList<>();
        for (Map.Entry<String, Integer> e : wanted.entrySet()) {
            Product p = productRepository.findById(e.getKey()).orElse(null);
            if (p == null) {
                return error(HttpStatus.NOT_FOUND, "product not found: " + e.getKey());
            }
            if (!p.isActive()) {
                return error(HttpStatus.CONFLICT, "product is inactive: " + e.getKey());
            }
            if (p.getStockQuantity() - p.getReservedQuantity() < e.getValue()) {
                return error(HttpStatus.CONFLICT, "insufficient stock for " + e.getKey());
            }
            products.add(p);
        }
        for (Product p : products) {
            int qty = wanted.get(p.getSku());
            p.setReservedQuantity(p.getReservedQuantity() + qty);
            reservationRepository.save(new StockReservation(orderRef, p.getSku(), qty, expiresAt));
        }
        productRepository.saveAll(products);
        return ResponseEntity.ok(summary(orderRef, "RESERVED", expiresAt));
    }

    // C6
    @PostMapping("/stock/release")
    @Transactional
    public ResponseEntity<Map<String, Object>> release(@RequestBody Map<String, Object> body) {
        String orderRef = text(body.get("orderRef"));
        if (orderRef == null) {
            return error(HttpStatus.BAD_REQUEST, "orderRef is required");
        }
        int released = 0;
        for (StockReservation r : reservationRepository.findByOrderRef(orderRef)) {
            if (StockReservation.ACTIVE.equals(r.getStatus())) {
                Product p = productRepository.findById(r.getSku()).orElseThrow(() -> new ProductNotFoundException(r.getSku()));
                p.setReservedQuantity(p.getReservedQuantity() - r.getQuantity());
                productRepository.save(p);
                r.setStatus(StockReservation.RELEASED);
                reservationRepository.save(r);
                released++;
            }
        }
        Map<String, Object> res = new LinkedHashMap<>();
        res.put("orderRef", orderRef);
        res.put("released", released);
        return ResponseEntity.ok(res);
    }

    // C7: confirm = reservation becomes a stock exit; restock=true puts confirmed quantities back
    @PostMapping("/stock/confirm")
    @Transactional
    public ResponseEntity<Map<String, Object>> confirm(@RequestBody Map<String, Object> body,
            @RequestParam(name = "restock", defaultValue = "false") boolean restock) {
        String orderRef = text(body.get("orderRef"));
        if (orderRef == null) {
            return error(HttpStatus.BAD_REQUEST, "orderRef is required");
        }
        List<StockReservation> reservations = reservationRepository.findByOrderRef(orderRef);
        if (restock) {
            return restock(orderRef, reservations, parseItems(body.get("items")));
        }

        if (reservations.isEmpty()) {
            return error(HttpStatus.CONFLICT, "no reservation for " + orderRef);
        }
        LocalDateTime now = LocalDateTime.now();
        boolean usable = true;
        for (StockReservation r : reservations) {
            if (!StockReservation.ACTIVE.equals(r.getStatus()) || !r.getExpiresAt().isAfter(now)) {
                usable = false;
            }
        }
        if (!usable) {
            for (StockReservation r : reservations) {
                if (StockReservation.ACTIVE.equals(r.getStatus())) {
                    expire(r);
                }
            }
            return error(HttpStatus.CONFLICT, "reservation is no longer active for " + orderRef);
        }
        for (StockReservation r : reservations) {
            Product p = productRepository.findById(r.getSku()).orElseThrow(() -> new ProductNotFoundException(r.getSku()));
            p.setReservedQuantity(p.getReservedQuantity() - r.getQuantity());
            p.setStockQuantity(p.getStockQuantity() - r.getQuantity());
            productRepository.save(p);
            r.setStatus(StockReservation.CONFIRMED);
            reservationRepository.save(r);
        }
        return ResponseEntity.ok(summary(orderRef, "CONFIRMED", null));
    }

    private ResponseEntity<Map<String, Object>> restock(String orderRef, List<StockReservation> reservations,
            Map<String, Integer> items) {
        if (items == null || items.isEmpty()) {
            return error(HttpStatus.BAD_REQUEST, "items must be a non-empty list of {sku, qty} with qty > 0");
        }
        Map<String, StockReservation> bySku = new LinkedHashMap<>();
        for (StockReservation r : reservations) {
            if (StockReservation.CONFIRMED.equals(r.getStatus())) {
                bySku.put(r.getSku(), r);
            }
        }
        for (Map.Entry<String, Integer> e : items.entrySet()) {
            StockReservation r = bySku.get(e.getKey());
            if (r == null) {
                return error(HttpStatus.CONFLICT, "nothing confirmed for " + e.getKey() + " on " + orderRef);
            }
            if (r.getRestockedQuantity() + e.getValue() > r.getQuantity()) {
                return error(HttpStatus.CONFLICT, "cannot restock more than confirmed for " + e.getKey());
            }
        }
        for (Map.Entry<String, Integer> e : items.entrySet()) {
            StockReservation r = bySku.get(e.getKey());
            Product p = productRepository.findById(e.getKey()).orElseThrow(() -> new ProductNotFoundException(e.getKey()));
            p.setStockQuantity(p.getStockQuantity() + e.getValue());
            productRepository.save(p);
            r.setRestockedQuantity(r.getRestockedQuantity() + e.getValue());
            reservationRepository.save(r);
        }
        return ResponseEntity.ok(summary(orderRef, "RESTOCKED", null));
    }

    public void expire(StockReservation r) {
        Product p = productRepository.findById(r.getSku()).orElseThrow(() -> new ProductNotFoundException(r.getSku()));
        p.setReservedQuantity(p.getReservedQuantity() - r.getQuantity());
        productRepository.save(p);
        r.setStatus(StockReservation.EXPIRED);
        reservationRepository.save(r);
    }

    private Map<String, Integer> parseItems(Object raw) {
        if (!(raw instanceof List<?> list)) {
            return null;
        }
        Map<String, Integer> result = new LinkedHashMap<>();
        for (Object o : list) {
            if (!(o instanceof Map<?, ?> m)) {
                return null;
            }
            String sku = text(m.get("sku"));
            Integer qty = integer(m.get("qty"));
            if (sku == null || qty == null || qty <= 0) {
                return null;
            }
            result.merge(sku, qty, Integer::sum);
        }
        return result;
    }

    private Map<String, Object> summary(String orderRef, String state, LocalDateTime expiresAt) {
        Map<String, Object> res = new LinkedHashMap<>();
        res.put("orderRef", orderRef);
        res.put("state", state);
        if (expiresAt != null) {
            res.put("expiresAt", expiresAt.toString());
        }
        return res;
    }

    private ResponseEntity<Map<String, Object>> error(HttpStatus status, String message) {
        Map<String, Object> res = new LinkedHashMap<>();
        res.put("message", message);
        return ResponseEntity.status(status).body(res);
    }

    private static String text(Object o) {
        if (o == null) {
            return null;
        }
        String s = String.valueOf(o).trim();
        return s.isEmpty() ? null : s;
    }

    private static Integer integer(Object o) {
        if (o == null) {
            return null;
        }
        try {
            return new java.math.BigDecimal(String.valueOf(o)).intValueExact();
        } catch (ArithmeticException | NumberFormatException e) {
            return null;
        }
    }
}
